SELECT CASE WHEN p.stock_qty >= 380 THEN 'high' WHEN p.stock_qty >= 149 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, p.brand, MAX(i.last_restock) AS last_last_restock, COUNT(*) AS num_inventory FROM inventory i RIGHT JOIN products p ON p.id = i.product_id INNER JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN p.stock_qty >= 380 THEN 'high' WHEN p.stock_qty >= 149 THEN 'mid' ELSE 'low' END, p.brand;
